import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Defect on the final round: no future retaliation possible.
    if n >= 99:
        return 'D'

    # Pure cooperator: exploit near the end, cooperate early to keep points flowing.
    if opp_d == 0:
        if n >= 90:
            return 'D' if rng.random() < 0.85 else 'C'
        if n >= 60:
            return 'D' if rng.random() < 0.20 else 'C'
        return 'C'

    # Pure defector: stop feeding them, but occasionally probe.
    if opp_c == 0:
        if n >= 8 and rng.random() < 0.06:
            return 'C'
        return 'D'

    # Very cooperative opponent (few defections).
    if opp_d <= max(1, n // 12):
        last_op = opp[-1]
        if last_op == 'D':
            # Retaliate lightly, but don't get stuck.
            return 'D' if rng.random() < 0.7 else 'C'
        if n >= 90:
            return 'D' if rng.random() < 0.55 else 'C'
        if n >= 65:
            return 'D' if rng.random() < 0.12 else 'C'
        return 'C'

    # Heavy defector: defend.
    if opp_d >= opp_c + 3:
        last_op = opp[-1]
        if last_op == 'C':
            # Reward cooperation to encourage a switch.
            return 'C' if rng.random() < 0.7 else 'D'
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Main reciprocal regime.
    last_me = me[-1]
    last_op = opp[-1]

    # Analyze recent window.
    w = min(10, n)
    recent = history[-w:]
    r_cc = r_cd = r_dc = r_dd = 0
    for a, b in recent:
        if a == 'C':
            if b == 'C': r_cc += 1
            else: r_cd += 1
        else:
            if b == 'C': r_dc += 1
            else: r_dd += 1

    # Mutual defection spiral: try to break out.
    if r_dd >= 4 and r_cc == 0:
        return 'C' if rng.random() < 0.7 else 'D'

    # Being exploited a lot: retaliate firmly.
    if r_cd >= 4:
        return 'D'

    # Our defections against their cooperation are paying off: keep exploiting.
    if r_dc >= 3 and r_cd == 0:
        return 'D' if rng.random() < 0.75 else 'C'

    # Opponent just defected.
    if last_op == 'D':
        if last_me == 'D':
            # We're already in mutual defection; occasionally offer olive branch.
            if r_dd >= 3 and rng.random() < 0.35:
                return 'C'
            return 'D'
        # We cooperated, they defected. Retaliate, but forgive occasionally.
        overall_opp_c_rate = opp_c / n
        if overall_opp_c_rate >= 0.6 and rng.random() < 0.30:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if n >= 92:
        # Endgame exploitation window.
        if rng.random() < 0.30:
            return 'D'
        return 'C'

    # Small probe against middling opponents, weaned down as match progresses.
    if n < 50 and rng.random() < 0.03:
        return 'D'

    return 'C'
